import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the golden vectors generated by `color_matching`'s v1 parity corpus.
///
/// The fixture is intentionally committed rather than fetched at test time, so
/// client/server solver drift fails deterministically and is reviewable.
final class WeightedSquaredErrorParityCorpusTests: XCTestCase {
    func testCorpusMetadataDescribesTheSupportedSolverContract() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
        XCTAssertTrue(corpus.scenarios.contains { $0.expected.tieBroke == true })
        XCTAssertTrue(corpus.scenarios.contains { $0.expected.selectedIndex == nil })
    }

    func testWeightedSquaredErrorAndSelectionMatchEveryCorpusScenario() throws {
        let scorer = WeightedSquaredErrorScorer()

        for scenario in try loadCorpus().scenarios {
            let weights = channelWeights(from: scenario.weights)
            let target = targetVector(from: scenario.target)
            let palette = scenario.palette.sorted { $0.index < $1.index }.map(paletteColor(from:))

            XCTAssertEqual(palette.count, scenario.palette.count, "\(scenario.id): palette indices must be contiguous")
            let scored = assertScores(
                scorer: scorer,
                palette: palette,
                target: target,
                weights: weights,
                expected: scenario.expected.scores,
                scenarioID: scenario.id
            )
            assertTieEvidence(scored: scored, expected: scenario.expected, scenarioID: scenario.id)
            try assertSelection(
                palette: palette,
                targetChannels: scenario.target.channels,
                weights: weights,
                expected: scenario.expected,
                scenarioID: scenario.id
            )
        }
    }

    private func assertScores(
        scorer: WeightedSquaredErrorScorer,
        palette: [PaletteColor],
        target: TargetResponseVector,
        weights: ChannelWeights,
        expected: [ExpectedScore],
        scenarioID: String
    ) -> [(index: Int, value: Double)] {
        XCTAssertEqual(expected.map(\.index), Array(palette.indices), "\(scenarioID): expected score indices")
        var scored: [(index: Int, value: Double)] = []

        for expectation in expected {
            let result = scorer.score(candidate: palette[expectation.index], target: target, weights: weights)
            switch (expectation.score, result) {
            case (.excluded, .excluded):
                break
            case (.value(let expectedValue), .score(let actualValue)):
                XCTAssertEqual(actualValue, expectedValue, accuracy: 1e-12, "\(scenarioID): candidate \(expectation.index)")
                scored.append((expectation.index, actualValue))
            default:
                XCTFail("\(scenarioID): candidate \(expectation.index) expected \(expectation.score), got \(result)")
            }
        }
        return scored
    }

    private func assertTieEvidence(
        scored: [(index: Int, value: Double)],
        expected: Expected,
        scenarioID: String
    ) {
        guard let error = expected.error else {
            XCTAssertNil(expected.tieBroke, "\(scenarioID): no selection has no tie decision")
            XCTAssertEqual(expected.tiedIndices, [], "\(scenarioID): no selection has no ties")
            return
        }

        let tiedIndices = scored.filter { $0.value == error }.map(\.index)
        XCTAssertEqual(tiedIndices, expected.tiedIndices, "\(scenarioID): tied candidate indices")
        XCTAssertEqual(expected.tieBroke, Optional(tiedIndices.count > 1), "\(scenarioID): tie flag")
        XCTAssertEqual(tiedIndices.first, expected.selectedIndex, "\(scenarioID): earliest tie must win")
    }

    private func assertSelection(
        palette: [PaletteColor],
        targetChannels: [String: Double],
        weights: ChannelWeights,
        expected: Expected,
        scenarioID: String
    ) throws {
        // The corpus deliberately contains a target missing a required channel.
        // That behavior is asserted above at scorer level; a composition cannot
        // be constructed without a grid for every active client channel.
        guard LightingCondition.all.allSatisfy({ weights.weight(for: $0) <= 0 || targetChannels[$0.rawValue] != nil }) else {
            XCTAssertNil(expected.selectedIndex, "\(scenarioID): incomplete targets must have no selection")
            return
        }

        let grids = Dictionary(uniqueKeysWithValues: LightingCondition.all.compactMap { condition in
            guard weights.weight(for: condition) > 0, let value = targetChannels[condition.rawValue] else { return nil }
            return (condition, BrightnessGrid(width: 1, height: 1, values: [value]))
        })
        let result = try CompositionSolver().solve(palette: palette, sourceGrids: grids, weights: weights)

        XCTAssertEqual(result.colorIndex(x: 0, y: 0), expected.selectedIndex, "\(scenarioID): selected index")
        if let selectedIndex = expected.selectedIndex {
            XCTAssertEqual(palette[selectedIndex].hex, expected.selectedHexColor, "\(scenarioID): selected color")
            XCTAssertEqual(result.error(x: 0, y: 0), expected.error!, accuracy: 1e-12, "\(scenarioID): selected error")
        } else {
            XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "\(scenarioID): all candidates should be excluded")
        }
    }

    private func loadCorpus() throws -> Corpus {
        let fixture = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/weighted_squared_error_v1.json")
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(Corpus.self, from: Data(contentsOf: fixture))
    }

    private func channelWeights(from encoded: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: encoded["white", default: 0], red: encoded["red", default: 0],
            green: encoded["green", default: 0], blue: encoded["blue", default: 0],
            lps: encoded["lps", default: 0]
        )
    }

    private func targetVector(from entry: Vector) -> TargetResponseVector {
        TargetResponseVector(channels(from: entry.channels))
    }

    private func paletteColor(from entry: PaletteEntry) -> PaletteColor {
        let rgb = RGBColor(hex: entry.hexColor)!
        let responses = channels(from: entry.channels).mapValues { IlluminationResponse(brightness: $0) }
        return PaletteColor(id: entry.index, hex: entry.hexColor, rgb: rgb, responses: responses)
    }

    private func channels(from encoded: [String: Double]) -> [LightingCondition: Double] {
        Dictionary(uniqueKeysWithValues: encoded.compactMap { name, value in
            LightingCondition(rawValue: name).map { ($0, value) }
        })
    }
}

private struct Corpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [Scenario]
}

private struct Scenario: Decodable {
    let id: String
    let weights: [String: Double]
    let target: Vector
    let palette: [PaletteEntry]
    let expected: Expected
}

private struct Vector: Decodable {
    let hexColor: String
    let channels: [String: Double]
}

private struct PaletteEntry: Decodable {
    let index: Int
    let hexColor: String
    let channels: [String: Double]
}

private struct Expected: Decodable {
    let scores: [ExpectedScore]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ExpectedScore: Decodable {
    enum Score: Equatable, CustomStringConvertible {
        case excluded
        case value(Double)

        var description: String {
            switch self {
            case .excluded: return "excluded"
            case .value(let value): return String(value)
            }
        }
    }

    let index: Int
    let score: Score

    private enum CodingKeys: String, CodingKey {
        case index
        case score
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        index = try container.decode(Int.self, forKey: .index)
        if let value = try? container.decode(Double.self, forKey: .score) {
            score = .value(value)
        } else {
            let value = try container.decode(String.self, forKey: .score)
            guard value == "excluded" else {
                throw DecodingError.dataCorruptedError(forKey: .score, in: container, debugDescription: "Unknown expected score: \(value)")
            }
            score = .excluded
        }
    }
}
